/**
 * business (окно 1440, сессия .qa/auth/business.json): новый кандидат «QA-AUTO-…» со ссылкой (link_only — без письма/SMS).
 * Своё окно 1440, а не окно проекта: форма бизнеса — десктопная (урок L-20261014-5), а тест может идти в проекте iphone/android.
 */
export async function newCandidateLink(browser: Browser, name: string, baseURL: string): Promise<string> {
  const ctx = await browser.newContext({
    storageState: path.resolve(__dirname, '../../../auth/business.json'),
    viewport: { width: 1440, height: 900 },
    locale: 'he-IL',
    baseURL,
  });
  try {
    const page = await ctx.newPage();
    return abs(await createCandidateLink(page, name));
  } finally {
    await ctx.close();
  }
}

export async function tapBtn(page: Page, name: string | RegExp) {
  const b = page.getByRole('button', { name }).first();
  await expect(b).toBeVisible({ timeout: 30_000 });
  await b.click();
}

