export type LayoutIssue = string;

/**
 * Замер текущего экрана: нет горизонтальной прокрутки; html dir=rtl lang=he; все видимые интерактивные элементы ≥44×44
 * (флажок/радио — по своему label); видимый текст не обрезан (overflow hidden/clip при scrollWidth > clientWidth);
 * кнопки и заголовки целиком в окне по горизонтали. Возвращает список нарушений (пустой — всё ок).
 */
export async function layoutIssues(page: Page): Promise<LayoutIssue[]> {
  return page.evaluate(() => {
    const out: string[] = [];
    const vw = window.innerWidth;
    const de = document.documentElement;
    if (de.scrollWidth > vw + 1) out.push(`горизонтальная прокрутка: scrollWidth ${de.scrollWidth} > ${vw}`);
    if (document.body.scrollWidth > vw + 1) out.push(`body.scrollWidth ${document.body.scrollWidth} > ${vw}`);
    if (de.getAttribute('dir') !== 'rtl') out.push(`html dir=${de.getAttribute('dir')}`);
    if (!(de.getAttribute('lang') || '').startsWith('he')) out.push(`html lang=${de.getAttribute('lang')}`);

    const visible = (e: Element) => {
      const r = e.getBoundingClientRect();
      if (r.width <= 2 || r.height <= 2) return false; // скрытый текст для читалки (sr-only)
      for (let x: Element | null = e; x; x = x.parentElement) {
        const cs = getComputedStyle(x);
        if (cs.display === 'none' || cs.visibility === 'hidden' || Number(cs.opacity) === 0) return false;
        if (x.getAttribute('aria-hidden') === 'true') return false;
      }
      return true;
    };
    const name = (e: Element) =>
      (e.getAttribute('aria-label') || (e as HTMLElement).innerText || (e as HTMLInputElement).value || e.getAttribute('title') || e.tagName)
        .replace(/\s+/g, ' ').trim().slice(0, 50);

    // Цели касания (AC2 / דרישה 8 «שטח מגע 44 על 44»).
    const sel = 'button, a[href], input:not([type=hidden]), select, textarea, [role=button], [role=radio], [role=checkbox], summary';
    for (const e of Array.from(document.querySelectorAll(sel))) {
      const target = (e.tagName === 'INPUT' && /checkbox|radio/.test((e as HTMLInputElement).type) && e.closest('label')) || e;
      if (!visible(target)) continue;
      const r = target.getBoundingClientRect();
      if (r.width < 43.5 || r.height < 43.5) out.push(`цель «${name(target)}» ${Math.round(r.width)}×${Math.round(r.height)} < 44`);
    }

    // Обрезка (AC4 «ללא חיתוך») и выход за окно.
    for (const e of Array.from(document.querySelectorAll('body *'))) {
      const el = e as HTMLElement;
      if (!el.innerText || !el.innerText.trim() || !visible(el)) continue;
      const cs = getComputedStyle(el);
      const clips = /hidden|clip/.test(cs.overflowX) || cs.textOverflow === 'ellipsis';
      if (clips && el.scrollWidth > el.clientWidth + 1 && el.children.length === 0) {
        out.push(`обрезан текст «${name(el)}» (${el.scrollWidth} > ${el.clientWidth})`);
      }
      if (/^(H1|H2|H3|BUTTON|A|LABEL)$/.test(el.tagName)) {
        const r = el.getBoundingClientRect();
        if (r.left < -1 || r.right > vw + 1) out.push(`«${name(el)}» за краем окна: ${Math.round(r.left)}…${Math.round(r.right)} при ширине ${vw}`);
      }
    }
    return out;
  });
}

/** Измерить экран на каждой ширине (в мобильных проектах — только своя ширина устройства). */
export async function expectLayoutOk(page: Page, label: string, widths: number[] | null) {
  const list = widths ?? [page.viewportSize()!.width];
  for (const w of list) {
    if (widths) await page.setViewportSize({ width: w, height: w < 768 ? 844 : 900 });
    const issues = await layoutIssues(page);
    expect(issues, `${label} @${w}`).toEqual([]);
  }
}

export type Focused = { tag: string; name: string; inSheet?: boolean; visibleRing: boolean; ring: string };

/** Элемент в фокусе и видна ли обводка (outline ≥2px не none, или box-shadow) — AC5 «מיקוד המקלדת נראה לעין». */
export async function focused(page: Page, sheetTitle?: string): Promise<Focused> {
  return page.evaluate((title) => {
    const e = document.activeElement as HTMLElement | null;
    if (!e || e === document.body) return { tag: 'BODY', name: '', visibleRing: false, ring: '' };
    const cs = getComputedStyle(e);
    const ow = parseFloat(cs.outlineWidth) || 0;
    const outline = cs.outlineStyle !== 'none' && ow >= 2 && !/rgba\(\d+, \d+, \d+, 0\)|transparent/.test(cs.outlineColor);
    const shadow = cs.boxShadow !== 'none' && cs.boxShadow !== '';
    let inSheet: boolean | undefined;
    if (title) {
      const h = Array.from(document.querySelectorAll('h1,h2,h3,[role=heading]')).find((x) => (x.textContent || '').trim() === title);
      let box: Element | null = h || null;
      while (box && !box.querySelector('button, input')) box = box.parentElement;
      inSheet = !!box && box.contains(e);
    }
    return {
      tag: e.tagName,
      name: (e.getAttribute('aria-label') || e.innerText || e.getAttribute('title') || '').replace(/\s+/g, ' ').trim().slice(0, 60),
      inSheet,
      visibleRing: outline || shadow,
      ring: `${cs.outlineStyle} ${cs.outlineWidth} ${cs.outlineColor} | ${cs.boxShadow}`,
    };
  }, sheetTitle);
}

/**
 * Tab до элемента с именем `target` (не больше `max` нажатий). Каждая остановка, кроме body/обёрток-section, должна иметь
 * видимую обводку. Возвращает имена остановок по порядку.
 */
export async function tabTo(page: Page, target: RegExp, max = 25): Promise<string[]> {
  const stops: string[] = [];
  for (let i = 0; i < max; i++) {
    await page.keyboard.press('Tab');
    const f = await focused(page);
    if (f.tag === 'BODY') continue;
    stops.push(f.name);
    const interactive = /^(BUTTON|A|INPUT|SELECT|TEXTAREA|SUMMARY)$/.test(f.tag);
    if (interactive) expect(f.visibleRing, `нет видимого фокуса на «${f.name}» (${f.ring})`).toBe(true);
    if (target.test(f.name)) return stops;
  }
  throw new Error(`за ${max} нажатий Tab не дошли до ${target}; остановки: ${stops.join(' → ')}`);
}

// ---------- Контраст (AC7 / דרישה 8 «ניגודיות 4.5:1») ----------

type TextBox = { name: string; x: number; y: number; w: number; h: number; rgba: number[]; large: boolean };

/** Видимые тексты окна (элементы с собственным текстом), их цвет с учётом прозрачности предков и размер. */
async function textBoxes(page: Page): Promise<TextBox[]> {
  return page.evaluate(() => {
    const out: TextBox[] = [];
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    for (const e of Array.from(document.querySelectorAll('body *'))) {
      const el = e as HTMLElement;
      const own = Array.from(el.childNodes).filter((n) => n.nodeType === 3).map((n) => n.textContent || '').join('').trim();
      if (!own) continue;
      if ((el as HTMLButtonElement).disabled || el.closest('[disabled],[aria-disabled=true],[aria-hidden=true],[inert]')) continue;
      const r = el.getBoundingClientRect();
      if (r.width <= 2 || r.height <= 2 || r.top < 0 || r.left < 0 || r.bottom > vh || r.right > vw) continue;
      let op = 1;
      let hidden = false;
      for (let x: Element | null = el; x; x = x.parentElement) {
        const cs = getComputedStyle(x);
        if (cs.display === 'none' || cs.visibility === 'hidden') hidden = true;
        op *= Number(cs.opacity);
      }
      if (hidden || op === 0) continue;
      // Текст под листом/подложкой не меряем — сверху другой слой (лист помощи, лист согласия).
      const hit = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
      if (!hit || !(hit === el || el.contains(hit) || hit.contains(el))) continue;
      const cs = getComputedStyle(el);
      const m = cs.color.match(/[\d.]+/g)!.map(Number);
      const fs = parseFloat(cs.fontSize);
      const bold = Number(cs.fontWeight) >= 700;
      out.push({
        name: own.replace(/\s+/g, ' ').slice(0, 40),
        x: r.left, y: r.top, w: r.width, h: r.height,
        rgba: [m[0], m[1], m[2], (m[3] ?? 1) * op],
        large: fs >= 24 || (bold && fs >= 18.66),
      });
    }
    return out;
  });
}

const lum = (c: number[]) => {
  const [r, g, b] = c.map((v) => {
    const s = v / 255;
    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};
export const contrast = (a: number[], b: number[]) => {
  const [l1, l2] = [lum(a), lum(b)].sort((x, y) => y - x);
  return (l1 + 0.05) / (l2 + 0.05);
};

/**
 * Контраст всех видимых текстов окна: снимок окна с прозрачным текстом → средний цвет фона под каждым текстом →
 * цвет текста (с альфой) поверх фона → отношение. Порог 4.5:1, крупный текст — 3:1. Неактивные (disabled) — исключение WCAG.
 */
export async function contrastIssues(page: Page, label: string): Promise<string[]> {
  const boxes = await textBoxes(page);
  const style = await page.addStyleTag({
    content: '*,*::before,*::after{color:transparent!important;-webkit-text-fill-color:transparent!important;text-shadow:none!important;caret-color:transparent!important;transition:none!important}::placeholder{color:transparent!important}',
  });
  let png: Buffer;
  try {
    png = await page.screenshot({ scale: 'css', animations: 'disabled' });
  } finally {
    await style.evaluate((s) => s.remove());
  }
  const probe = await page.context().newPage();
  try {
    await probe.setContent('<canvas></canvas>');
    const bgs: number[][] = await probe.evaluate(
      async ({ b64, list }) => {
        const img = new Image();
        img.src = `data:image/png;base64,${b64}`;
        await img.decode();
        const c = document.querySelector('canvas')!;
        c.width = img.width;
        c.height = img.height;
        const ctx = c.getContext('2d')!;
        ctx.drawImage(img, 0, 0);
        return list.map((b) => {
          const x = Math.max(0, Math.floor(b.x));
          const y = Math.max(0, Math.floor(b.y));
          const w = Math.max(1, Math.min(img.width - x, Math.floor(b.w)));
          const h = Math.max(1, Math.min(img.height - y, Math.floor(b.h)));
          const d = ctx.getImageData(x, y, w, h).data;
          const s = [0, 0, 0];
          for (let i = 0; i < d.length; i += 4) { s[0] += d[i]; s[1] += d[i + 1]; s[2] += d[i + 2]; }
          const n = d.length / 4;
          return s.map((v) => v / n);
        });
      },
      { b64: png.toString('base64'), list: boxes.map(({ x, y, w, h }) => ({ x, y, w, h })) },
    );
    const out: string[] = [];
    boxes.forEach((b, i) => {
      const bg = bgs[i];
      const a = Math.min(1, b.rgba[3]);
      const fg = [0, 1, 2].map((k) => b.rgba[k] * a + bg[k] * (1 - a));
      const cr = contrast(fg, bg);
      const need = b.large ? 3 : 4.5;
      if (cr < need) out.push(`${label}: «${b.name}» ${cr.toFixed(2)}:1 < ${need} (текст ${fg.map(Math.round).join(',')} на ${bg.map(Math.round).join(',')})`);
    });
    return out;
  } finally {
    await probe.close();
  }
}

/** Контраст по всему экрану: окно прокручивается по высоте, каждый текст меряется, когда целиком в окне. */
export async function expectContrastOk(page: Page, label: string) {
  const issues = new Set<string>();
  const { sh, vh } = await page.evaluate(() => ({ sh: document.documentElement.scrollHeight, vh: window.innerHeight }));
  for (let y = 0; y < sh; y += Math.max(200, vh - 100)) {
    await page.evaluate((top) => window.scrollTo(0, top), y);
    for (const s of await contrastIssues(page, `${label} (scrollY ${y})`)) issues.add(s);
    if (y + vh >= sh) break;
  }
  await page.evaluate(() => window.scrollTo(0, 0));
  expect([...issues], `контраст ${label}`).toEqual([]);
}

/** Подмена «браузер без микрофона»: navigator.mediaDevices = undefined (до загрузки страницы). */
export const NO_MEDIA_DEVICES = () => {
  try {
    Object.defineProperty(Navigator.prototype, 'mediaDevices', { get: () => undefined, configurable: true });
  } catch {
    /* noop */
  }
  try {
    Object.defineProperty(navigator, 'mediaDevices', { get: () => undefined, configurable: true });
  } catch {
    /* noop */
  }
};
